const GROUPS=['A','B','C','D'];
const MATCHES=[['A','B','C'],['A','B','D'],['A','C','D'],['B','C','D']];
const COLORS=['pink','black','gray'];
const TITLES={dashboard:'오늘의 수업',scoreboard:'스마트 점수판',activityTimer:'활동 타이머',league:'조별 리그',tournament:'학급대항전',students:'학생 명단',introLesson:'킨볼 첫 수업',rules:'킨볼 규칙',signals:'심판 수신호',settings:'데이터 관리'};
const makeMatches=()=>Array.from({length:4},(_,cycle)=>MATCHES.map((teams,round)=>({id:cycle*4+round+1,cycle:cycle+1,round:round+1,teams:[...teams],scores:[0,0,0],done:false}))).flat();
const blankClass=()=>({students:[],matches:makeMatches()});
const makeClassMeet=()=>({representatives:Object.fromEntries(Array.from({length:8},(_,i)=>[i+1,''])),games:Array.from({length:8},(_,i)=>({id:i+1,referee:i+1,classes:[(i+1)%8+1,(i+3)%8+1,(i+4)%8+1],scores:[0,0,0],done:false}))});
const initial=()=>({selectedClass:1,classes:Object.fromEntries(Array.from({length:8},(_,i)=>[i+1,blankClass()])),tournament:[],classMeet:makeClassMeet(),lessons:[],activeLesson:{date:new Date().toISOString().slice(0,10),period:1,title:'1차시'}});
let state=load(); let activeGroup='전체'; let seconds=600,timerId=null,meetSeconds=600,meetTimerId=null,activeMeetGame=1;
function load(){try{const d=JSON.parse(localStorage.getItem('kinball-class-v1'));if(!d?.classes)return initial();Object.values(d.classes).forEach(c=>{const saved=c.matches||[],expanded=makeMatches();saved.slice(0,16).forEach((m,i)=>expanded[i]={...expanded[i],...m,id:i+1,cycle:Math.floor(i/4)+1,round:i%4+1,teams:[...expanded[i].teams]});c.matches=expanded;c.students=c.students||[]});d.tournament=d.tournament||[];if(!d.classMeet)d.classMeet=makeClassMeet();return d}catch{return initial()}}
const CLOUD_API='https://kinball-awards-school.jsh911016.chatgpt.site/api/class-data';
let cloudSaveTimer=null;
function save(){state.lastLocalSave=new Date().toISOString();localStorage.setItem('kinball-class-v1',JSON.stringify(state));setCloudState('saving','저장 중');if(sessionStorage.getItem('kinball-cloud-pin')){clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(syncCloud,700)}else setTimeout(()=>setCloudState('offline','기기 저장'),250)}
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
save();
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}
function current(){return state.classes[state.selectedClass]}
function showView(id){$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===id));$('#pageTitle').textContent=TITLES[id]||'활동 타이머';document.body.classList.remove('nav-open');$('.sidebar').classList.remove('open');render()}
function rankFor(c){const rows=Object.fromEntries(GROUPS.map(g=>[g,{g,p:0,w:0,d:0,l:0,gf:0,ga:0,pts:0}]));c.matches.filter(m=>m.done).forEach(m=>{const max=Math.max(...m.scores),wins=m.scores.filter(x=>x===max).length;m.teams.forEach((g,i)=>{const r=rows[g];r.p++;r.gf+=m.scores[i];r.ga+=m.scores.reduce((a,x,j)=>a+(j===i?0:x),0);if(m.scores[i]===max&&wins===1){r.w++;r.pts+=3}else if(m.scores[i]===max){r.d++;r.pts++}else r.l++})});return Object.values(rows).sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf)}
function render(){const c=current();$('#heroClass').textContent=`${state.selectedClass}반`;$('#leagueClass').textContent=`${state.selectedClass}반`;$('#rosterClass').textContent=`${state.selectedClass}반`;$('#studentCount').textContent=c.students.length;$('#attendance').textContent=c.students.filter(s=>s.present).length;$('#gameCount').textContent=c.matches.filter(m=>m.done).length;const ranks=rankFor(c);$('#leader').textContent=c.matches.some(m=>m.done)?ranks[0].g:'-';renderSchedule();renderStandings();renderScoreboard();renderStudents();renderTournament();renderTeamBalance();renderLineupGuide()}
function renderSchedule(){const c=current(),next=c.matches.findIndex(m=>!m.done),start=next<0?Math.max(0,c.matches.length-3):next;$('#miniSchedule').innerHTML=c.matches.slice(start,start+3).map(m=>`<div class="mini-game"><span class="round">${m.cycle}C-${m.round}</span><div class="teams">${m.teams.map(t=>`<span>${t}</span>`).join('')}</div><span class="game-state">${m.done?m.scores.join(' : '):'예정'}</span></div>`).join('');$('#scheduleGrid').innerHTML=Array.from({length:4},(_,i)=>{const cycle=i+1;return `<div class="cycle-divider"><span>${cycle}사이클</span><small>${cycle*4-3}~${cycle*4}경기</small></div>`+c.matches.filter(m=>m.cycle===cycle).map(m=>`<article class="game-card card"><div class="game-card-head"><b>${m.id}경기 <em>${m.cycle}사이클 ${m.round}경기</em></b><span>${m.done?'경기 완료':'진행 예정'}</span></div><div class="game-teams">${m.teams.map((t,j)=>`<div><b>${t}조</b><input type="number" min="0" value="${m.scores[j]}" data-match="${m.id}" data-score="${j}"></div>`).join('<i>:</i>')}</div><button class="btn ${m.done?'secondary':'primary'} save-result" data-match="${m.id}">${m.done?'결과 수정':'결과 저장'}</button></article>`).join('')}).join('');$$('[data-score]').forEach(x=>x.oninput=e=>{const m=c.matches[e.target.dataset.match-1];m.scores[+e.target.dataset.score]=Math.max(0,+e.target.value||0)});$$('.save-result').forEach(b=>b.onclick=()=>{c.matches[b.dataset.match-1].done=true;save();render();toast(`${c.matches[b.dataset.match-1].cycle}사이클 경기 결과가 반영됐어요`)})}
function renderStandings(){const rows=rankFor(current());$('#standingsBody').innerHTML=rows.map((r,i)=>`<tr><td class="rank">${i+1}</td><td><span class="team-chip">${r.g}</span></td><td>${r.p}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.gf}</td><td>${r.ga}</td><td>${r.gf-r.ga}</td><td><b>${r.pts}</b></td></tr>`).join('')}
function renderScoreboard(){const c=current(),fallback=(c.matches.find(m=>!m.done)||c.matches[0]).id,sel=+($('#matchSelect').value||fallback),m=c.matches[sel-1]||c.matches[0];$('#matchSelect').innerHTML=c.matches.map(x=>`<option value="${x.id}" ${x.id===m.id?'selected':''}>${x.cycle}사이클 ${x.round}경기 · ${x.teams.join(' / ')}</option>`).join('');$('#matchLabel').textContent=`${m.cycle}사이클 ${m.round}경기 · ${m.teams.join(' · ')}`;$('#scoreGrid').innerHTML=m.teams.map((t,i)=>`<article class="team-score ${COLORS[i]}"><small>${COLORS[i].toUpperCase()} TEAM</small><h2>${t}조</h2><div class="big-score">${m.scores[i]}</div><div class="score-buttons"><button class="point" data-point="${i}">+ 1 득점</button><button data-foul="${i}">파울</button></div></article>`).join('');$$('[data-point]').forEach(b=>b.onclick=()=>adjust(m,+b.dataset.point,1));$$('[data-foul]').forEach(b=>b.onclick=()=>{m.scores=m.scores.map((x,i)=>i===+b.dataset.foul?x:x+1);beep(180,.18);save();render();toast(`${m.teams[b.dataset.foul]}조 파울 · 나머지 두 팀 +1`)})}
function adjust(m,i,n){m.scores[i]=Math.max(0,m.scores[i]+n);beep(n>0?640:300,.08);save();render()}
function renderStudents(){const c=current();$('#groupTabs').innerHTML=['전체',...GROUPS].map(g=>`<button class="${g===activeGroup?'active':''}" data-group="${g}">${g}${g==='전체'?'':'조'}</button>`).join('');$$('[data-group]').forEach(b=>b.onclick=()=>{activeGroup=b.dataset.group;renderStudents()});const list=c.students.filter(s=>activeGroup==='전체'||s.group===activeGroup).sort((a,b)=>a.no-b.no);$('#emptyStudents').style.display=list.length?'none':'block';$('#studentBody').innerHTML=list.map(s=>`<tr><td><input type="checkbox" data-present="${s.id}" ${s.present?'checked':''}></td><td>${s.no}</td><td><b>${s.name}</b></td><td><span class="team-chip">${s.group}</span></td><td><button class="text-btn" data-delete-student="${s.id}">삭제</button></td></tr>`).join('');$$('[data-present]').forEach(x=>x.onchange=()=>{c.students.find(s=>s.id==x.dataset.present).present=x.checked;save();render()});$$('[data-delete-student]').forEach(b=>b.onclick=()=>{c.students=c.students.filter(s=>s.id!=b.dataset.deleteStudent);save();render()})}
function renderTournament(){const meet=state.classMeet||(state.classMeet=makeClassMeet()),stats=Object.fromEntries(Array.from({length:8},(_,i)=>[i+1,{c:i+1,p:0,w:0,d:0,l:0,gf:0,pts:0}]));meet.games.filter(g=>g.done).forEach(g=>{const max=Math.max(...g.scores),ties=g.scores.filter(x=>x===max).length;g.classes.forEach((c,i)=>{const r=stats[c];r.p++;r.gf+=g.scores[i];if(g.scores[i]===max&&ties===1){r.w++;r.pts+=3}else if(g.scores[i]===max){r.d++;r.pts++}else r.l++})});const ranked=Object.values(stats).sort((a,b)=>b.pts-a.pts||b.w-a.w||b.gf-a.gf||a.c-b.c);ranked.forEach((r,i)=>r.rank=i+1);const rankMap=Object.fromEntries(ranked.map(r=>[r.c,r]));$('#meetMatrixBody').innerHTML=Array.from({length:8},(_,i)=>{const c=i+1,r=rankMap[c];return `<tr><td><b>${c}반</b></td><td class="rep-cell">${meet.representatives[c]||'<span>미등록</span>'}</td>${meet.games.map(g=>`<td class="meet-role ${g.referee===c?'referee':g.classes.includes(c)?'player':'rest'}">${g.referee===c?'심판':g.classes.includes(c)?'출전':'-'}</td>`).join('')}<td class="meet-points">${r.pts}</td><td class="rank">${r.rank}</td></tr>`}).join('');$('#classRankBody').innerHTML=ranked.map(r=>`<tr><td class="rank">${r.rank}</td><td><b>${r.c}반</b></td><td class="rep-cell">${meet.representatives[r.c]||'<span>미등록</span>'}</td><td>${r.p}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.gf}</td><td><b>${r.pts}</b></td></tr>`).join('');$('#tournamentGames').innerHTML=meet.games.map(g=>`<article class="game-card meet-game card"><div class="game-card-head"><b>${g.id}경기</b><span class="ref-badge">심판 ${g.referee}반</span></div><div class="class-color-row">${g.classes.map((c,i)=>`<span class="${COLORS[i]}">${COLORS[i]==='pink'?'핑크':COLORS[i]==='black'?'블랙':'그레이'} · ${c}반</span>`).join('')}</div><div class="game-teams">${g.classes.map((c,i)=>`<div><b>${c}반</b><small>${meet.representatives[c]||'대표 미등록'}</small><input type="number" min="0" value="${g.scores[i]}" data-meet-game="${g.id}" data-meet-score="${i}"></div>`).join('<i>:</i>')}</div><div class="meet-card-actions"><button class="btn score-open" data-open-meet="${g.id}">스마트 점수판</button><button class="btn ${g.done?'secondary':'primary'} save-meet" data-meet-game="${g.id}">${g.done?'결과 수정':'결과 저장'}</button></div></article>`).join('');$$('[data-meet-score]').forEach(x=>x.oninput=e=>{meet.games[e.target.dataset.meetGame-1].scores[+e.target.dataset.meetScore]=Math.max(0,+e.target.value||0)});$$('.save-meet').forEach(b=>b.onclick=()=>{meet.games[b.dataset.meetGame-1].done=true;save();render();toast(`${b.dataset.meetGame}경기 결과를 반영했어요`)});$$('[data-open-meet]').forEach(b=>b.onclick=()=>openMeetScoreboard(+b.dataset.openMeet))}

function updateMeetTimer(){const m=Math.floor(meetSeconds/60),s=meetSeconds%60;$('#meetTimer').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function renderMeetScoreboard(){const meet=state.classMeet||(state.classMeet=makeClassMeet()),g=meet.games[activeMeetGame-1]||meet.games[0];activeMeetGame=g.id;$('#meetScoreMatchLabel').textContent=`${g.id}경기 · 심판 ${g.referee}반`;$('#meetScoreSelect').innerHTML=meet.games.map(x=>`<option value="${x.id}" ${x.id===g.id?'selected':''}>${x.id}경기 · ${x.classes.join('반 / ')}반</option>`).join('');$('#meetScoreGrid').innerHTML=g.classes.map((c,i)=>`<article class="meet-team-score ${COLORS[i]}"><small>${COLORS[i]==='pink'?'PINK':COLORS[i]==='black'?'BLACK':'GRAY'} TEAM</small><h2>${c}반</h2><p>${meet.representatives[c]||'대표 선수 미등록'}</p><strong>${g.scores[i]}</strong><div><button class="meet-point" data-meet-point="${i}">+ 1 득점</button><button data-meet-foul="${i}">파울</button></div></article>`).join('');$$('[data-meet-point]').forEach(b=>b.onclick=()=>adjustMeetScore(+b.dataset.meetPoint,1));$$('[data-meet-foul]').forEach(b=>b.onclick=()=>{const game=meet.games[activeMeetGame-1],i=+b.dataset.meetFoul;game.scores=game.scores.map((x,j)=>j===i?x:x+1);save();beep(180,.18);renderMeetScoreboard();toast(`${game.classes[i]}반 파울 · 나머지 두 반 +1`)})}
function adjustMeetScore(i,n){const g=state.classMeet.games[activeMeetGame-1];g.scores[i]=Math.max(0,g.scores[i]+n);save();beep(n>0?640:300,.08);renderMeetScoreboard()}
function openMeetScoreboard(id){activeMeetGame=id;renderMeetScoreboard();$('#meetScoreOverlay').classList.add('open');$('#meetScoreOverlay').setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}
function closeMeetScoreboard(){clearInterval(meetTimerId);meetTimerId=null;$('#meetTimerToggle').textContent='시작';$('#meetScoreOverlay').classList.remove('open');$('#meetScoreOverlay').setAttribute('aria-hidden','true');document.body.style.overflow='';render()}
function modal(title,html,onSave){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modalSave').textContent='저장';const d=$('#modal');d.showModal();$('#modalForm').onsubmit=e=>{e.preventDefault();onSave(new FormData(e.target));d.close()}}
function beep(freq=600,dur=.12){try{const a=new AudioContext(),o=a.createOscillator(),g=a.createGain();o.frequency.value=freq;o.connect(g);g.connect(a.destination);g.gain.setValueAtTime(.12,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+dur);o.start();o.stop(a.currentTime+dur)}catch{}}
function updateTimer(){const m=Math.floor(seconds/60),s=seconds%60;$('#timer').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
document.addEventListener('DOMContentLoaded',()=>{const cs=$('#classSelect');cs.innerHTML=Array.from({length:8},(_,i)=>`<option value="${i+1}">${i+1}반</option>`).join('');cs.value=state.selectedClass;$('#todayLabel').textContent=new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'long'}).format(new Date());cs.onchange=()=>{state.selectedClass=+cs.value;save();render()};$$('.nav-item').forEach(b=>b.onclick=()=>showView(b.dataset.view));$$('[data-go]').forEach(b=>b.onclick=()=>showView(b.dataset.go));$('#menuBtn').onclick=()=>$('.sidebar').classList.toggle('open');$('#matchSelect').onchange=renderScoreboard;$('#timerToggle').onclick=()=>{if(timerId){clearInterval(timerId);timerId=null;$('#timerToggle').textContent='시작'}else{timerId=setInterval(()=>{if(seconds<=0){clearInterval(timerId);timerId=null;beep(880,1);$('#timerToggle').textContent='시작';toast('경기가 종료됐어요')}else{seconds--;updateTimer()}},1000);$('#timerToggle').textContent='일시정지'}};$('#timerReset').onclick=()=>{clearInterval(timerId);timerId=null;seconds=600;updateTimer();$('#timerToggle').textContent='시작'};$('#endMatch').onclick=()=>{const m=current().matches[+$('#matchSelect').value-1];m.done=true;save();beep(820,.7);render();toast('경기를 종료하고 순위를 계산했어요')};$('#resetLeague').onclick=()=>{if(confirm('현재 반의 모든 리그 점수를 초기화할까요?')){state.classes[state.selectedClass].matches=blankClass().matches;save();render()}};$('#addStudent').onclick=()=>modal('학생 추가',`<div class="triple"><label class="field">번호<input name="no" type="number" min="1" required></label><label class="field">이름<input name="name" required></label><label class="field">소속 조<select name="group">${GROUPS.map(g=>`<option>${g}</option>`).join('')}</select></label></div>`,f=>{current().students.push({id:Date.now(),no:+f.get('no'),name:f.get('name').trim(),group:f.get('group'),present:true});save();render();toast('학생을 명단에 추가했어요')});$('#addTournament').onclick=()=>modal('학급대항전 결과',`<div class="triple">${[0,1,2].map(i=>`<div><label class="field">학급<select name="c${i}">${Array.from({length:8},(_,j)=>`<option value="${j+1}">${j+1}반</option>`).join('')}</select></label><label class="field">점수<input name="s${i}" type="number" min="0" value="0" required></label></div>`).join('')}</div>`,f=>{const classes=[0,1,2].map(i=>+f.get('c'+i));if(new Set(classes).size<3)return toast('서로 다른 세 반을 선택하세요');state.tournament.push({classes,scores:[0,1,2].map(i=>+f.get('s'+i))});save();render();toast('학급대항전 결과를 저장했어요')});$('#exportData').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`킨볼-수업-백업-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)};$('#importData').onchange=e=>{const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!d.classes)throw 0;state=d;save();render();toast('백업 데이터를 복원했어요')}catch{toast('올바른 백업 파일이 아니에요')}};r.readAsText(e.target.files[0])};['printBtn','printSettings'].forEach(id=>$('#'+id).onclick=()=>window.print());render();updateTimer()});

const signalBoard=$('#signalBoard');
function toggleSignalBoard(){signalBoard.classList.toggle('fullscreen-board');document.body.style.overflow=signalBoard.classList.contains('fullscreen-board')?'hidden':'';signalBoard.querySelector('figcaption').textContent=signalBoard.classList.contains('fullscreen-board')?'화면을 누르면 닫힙니다':'이미지를 누르면 크게 볼 수 있습니다.'}
$('#signalFullscreen').onclick=toggleSignalBoard;
signalBoard.querySelector('img').onclick=toggleSignalBoard;
signalBoard.querySelector('figcaption').onclick=()=>{if(signalBoard.classList.contains('fullscreen-board'))toggleSignalBoard()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&signalBoard.classList.contains('fullscreen-board'))toggleSignalBoard()});

document.addEventListener('DOMContentLoaded',()=>{
  $('#addTournament').onclick=()=>{const meet=state.classMeet||(state.classMeet=makeClassMeet());const safe=v=>String(v||'').replaceAll('&','&amp;').replaceAll('"','&quot;');modal('학급대표 등록',`<p class="modal-help">각 반 대표 선수의 이름을 쉼표로 구분해 입력하세요.</p><div class="rep-form">${Array.from({length:8},(_,i)=>`<label class="field"><b>${i+1}반</b><input name="rep${i+1}" value="${safe(meet.representatives[i+1])}" placeholder="예: 김하늘, 이로운, 박지민, 최서준"></label>`).join('')}</div>`,f=>{for(let c=1;c<=8;c++)meet.representatives[c]=String(f.get('rep'+c)||'').trim();save();render();toast('8개 반 대표 명단을 저장했어요')})};
  $('#resetClassMeet').onclick=()=>{if(confirm('학급대표 명단과 8경기 결과를 모두 초기화할까요?')){state.classMeet=makeClassMeet();save();render();toast('학급대항전을 초기화했어요')}};
  $('#bulkStudents').onclick=()=>modal('학생 명단 일괄 추가',`<div class="bulk-help"><b>엑셀 명단을 그대로 붙여넣으세요.</b><p>한 줄에 한 명씩 입력합니다. 조를 생략하면 A·B·C·D조로 고르게 자동 배정됩니다.</p><code>1 김하늘 A<br>2 이로운 B<br>3 박지민<br>4 최서준</code></div><label class="field">학생 명단<textarea name="roster" rows="12" placeholder="1 김하늘 A&#10;2 이로운 B&#10;3 박지민&#10;4 최서준" required></textarea></label>`,f=>{const c=current(),lines=String(f.get('roster')||'').split(/\r?\n/).map(x=>x.trim()).filter(x=>x&&!/^(번호|학번)[\s,\t]/.test(x)),start=Math.max(0,...c.students.map(s=>+s.no||0))+1;let added=0,updated=0;lines.forEach((line,i)=>{let parts=line.split(/[\t,]+|\s+/).map(x=>x.trim()).filter(Boolean),no,name,group;const first=parts.shift();if(/^\d+$/.test(first)){no=+first;name=parts.shift()}else{no=start+i;name=first}const last=parts.at(-1)||'';const normalized=last.toUpperCase().replace('조','');if(GROUPS.includes(normalized))group=normalized;else if(name&&GROUPS.includes(String(name).toUpperCase().replace('조',''))){group=String(name).toUpperCase().replace('조','');name=parts.shift()}if(!group)group=GROUPS[i%4];if(!name)return;const old=c.students.find(s=>+s.no===no);if(old){old.name=name;old.group=group;updated++}else{c.students.push({id:Date.now()+i,no,name,group,present:true});added++}});save();render();toast(`${added}명 추가${updated?` · ${updated}명 수정`:''}했어요`)})
});

// Standalone classroom activity timer
let activitySeconds=300,activityTotal=300,activityTimerId=null;
function renderActivityTimer(){const clock=$('#activityClock'),runner=$('#activityRunner'),progress=$('#activityProgress'),status=$('#activityStatus');if(!clock)return;const mins=Math.floor(activitySeconds/60),secs=activitySeconds%60,pct=activityTotal?Math.min(100,Math.max(0,(activityTotal-activitySeconds)/activityTotal*100)):0;clock.textContent=`${String(mins).padStart(2,'0')}:${String(secs).padStart(2,'0')}`;clock.classList.toggle('urgent',activitySeconds>0&&activitySeconds<=10);runner.style.left=`calc(${Math.min(82,pct*.82)}% + 4%)`;progress.style.width=pct+'%';runner.classList.toggle('running',!!activityTimerId);runner.classList.toggle('finished',activitySeconds===0);status.className='activity-status '+(activitySeconds===0?'finished':activityTimerId?'running':'');status.querySelector('span').textContent=activitySeconds===0?'도착! 정말 잘했어요':activityTimerId?'신나게 달리는 중':'준비됐어요';const toggle=$('#activityToggle');toggle.innerHTML=activityTimerId?'<span>Ⅱ</span> 일시정지':'<span>▶</span> '+(activitySeconds<activityTotal&&activitySeconds>0?'계속하기':'시작하기')}
function stopActivityTimer(){clearInterval(activityTimerId);activityTimerId=null}
function toggleActivityTimer(){if(activitySeconds<=0){activitySeconds=activityTotal}if(activityTimerId){stopActivityTimer();renderActivityTimer();return}activityTimerId=setInterval(()=>{activitySeconds=Math.max(0,activitySeconds-1);if(activitySeconds===0){stopActivityTimer();beep(880,.25);setTimeout(()=>beep(1040,.5),280);toast('활동 시간 끝! 토끼가 결승선에 도착했어요 🎉')}renderActivityTimer()},1000);renderActivityTimer()}
document.addEventListener('DOMContentLoaded',()=>{const toggle=$('#activityToggle'),reset=$('#activityReset');if(!toggle)return;toggle.onclick=toggleActivityTimer;reset.onclick=()=>{stopActivityTimer();activitySeconds=300;activityTotal=300;renderActivityTimer();toast('타이머를 5분으로 초기화했어요')};$$('[data-add-time]').forEach(button=>button.onclick=()=>{const add=+button.dataset.addTime;activitySeconds+=add;activityTotal+=add;renderActivityTimer();toast(`${add===30?'30초':add/60+'분'}를 추가했어요`)});renderActivityTimer()});

