function lessonSnapshot(){return {id:Date.now(),classId:state.selectedClass,date:state.activeLesson.date,period:state.activeLesson.period,title:state.activeLesson.title,savedAt:new Date().toISOString(),matches:structuredClone(current().matches),students:structuredClone(current().students)}}
