function showSemesterSummary(){const list=[...state.lessons.filter(x=>x.classId===state.selectedClass),lessonSnapshot()],unique=[...new Map(list.map(x=>[`${x.date}-${x.period}`,x])).values()],games=unique.flatMap(x=>x.matches.filter(m=>m.done));modal('학기 누적 기록',`<div class="lesson-report"><b>${state.settings.grade}학년 ${state.selectedClass}반</b><span>저장 수업 ${unique.length}회</span><span>완료 경기 ${games.length}회</span><span>누적 득점 ${games.reduce((a,m)=>a+m.scores.reduce((s,n)=>s+n,0),0)}점</span></div>`,()=>{});$('#modalSave').textContent='확인'}
function scoreLog(m,type,text,before,after){const entry={id:crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`,at:new Date().toISOString(),classId:state.selectedClass,matchId:m.id,type,text,before:[...before],after:[...after]};m.scoreHistory=m.scoreHistory||[];m.scoreHistory.push(entry);if(m.scoreHistory.length>100)m.scoreHistory.shift();scoreHistory=current().matches.flatMap(x=>x.scoreHistory||[]);if(type==='foul')lastFoulEntry=entry;renderScoreHistory()}
function persistedScoreHistory(){return current().matches.flatMap(m=>m.scoreHistory||[]).sort((a,b)=>a.at.localeCompare(b.at))}
function restoreScoreAudit(){scoreHistory=persistedScoreHistory();lastFoulEntry=[...scoreHistory].reverse().find(x=>x.type==='foul'&&!scoreHistory.some(y=>y.type==='undo'&&y.undoId===x.id))||null}
function renderScoreHistory(){const el=$('#scoreHistoryList');if(!el)return;const items=persistedScoreHistory().slice(-12).reverse();el.innerHTML=items.length?items.map(x=>`<div class="history-entry ${x.type==='foul'?'foul':''}"><span>${new Date(x.at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',second:'2-digit'})} · ${x.matchId}경기 · ${x.text}</span><b>${x.before.join(':')} → ${x.after.join(':')}</b></div>`).join(''):'<p>아직 점수 변경 기록이 없습니다.</p>'}
function confirmFoul(m,index){const receivers=m.teams.filter((_,i)=>i!==index);if(!confirm(`${m.teams[index]}조 파울 → ${receivers.join('·')}조 +1\n점수를 반영할까요?`))return;const before=[...m.scores];m.scores=m.scores.map((x,i)=>i===index?x:x+1);scoreLog(m,'foul',`${m.teams[index]}조 파울`,before,m.scores);beep(180,.18);save();render();toast(`${m.teams[index]}조 파울 · ${receivers.join('·')}조 +1`)}
function undoLastFoul(){restoreScoreAudit();if(!lastFoulEntry)return toast('취소할 파울이 없어요');const foul=lastFoulEntry,m=current().matches[foul.matchId-1];if(!m)return;const before=[...m.scores];m.scores=[...foul.before];scoreLog(m,'undo','직전 파울 취소',before,m.scores);m.scoreHistory[m.scoreHistory.length-1].undoId=foul.id;lastFoulEntry=null;save();render();toast(`취소 완료: ${foul.text} · ${before.join(':')} → ${m.scores.join(':')}`)}
function lineupFor(m,g){m.lineup=m.lineup||{};const valid=current().students.filter(s=>s.group===g&&s.present).sort((a,b)=>a.no-b.no),saved=(m.lineup[g]||[]).map(id=>valid.find(s=>s.id===id)).filter(Boolean),auto=rotatingPlayers(g,m.id);return [...saved,...auto.filter(s=>!saved.some(x=>x.id===s.id))].slice(0,Math.min(4,valid.length))}
