function renderLineupGuideEnhanced(){const el=$('#lineupGuide');if(!el)return;const c=current(),fallback=(c.matches.find(m=>!m.done)||c.matches[0]).id,id=+($('#matchSelect')?.value||fallback),m=c.matches[id-1]||c.matches[0],next=c.matches[id]||null,card=(game,label)=>game?`<div class="lineup-game"><span>${label} · ${game.cycle}C-${game.round}</span>${game.teams.map(g=>lineupEditor(game,g)).join('')}<div class="lineup-team"><b>심판</b><em>${refereeFor(game)}조</em></div></div>`:`<div class="lineup-game"><span>${label}</span><em>마지막 경기입니다.</em></div>`;el.className='lineup-games';el.innerHTML=card(m,'현재 경기')+card(next,'다음 경기');$$('[data-lineup-group]').forEach(box=>box.onchange=()=>{const game=box.closest('.lineup-game').querySelector('span').textContent.startsWith('현재')?m:next;if(!game)return;const ids=[...box.querySelectorAll('select')].map(s=>+s.value);if(new Set(ids).size!==ids.length)return toast('같은 학생을 중복 출전시킬 수 없어요');game.lineup=game.lineup||{};game.lineup[box.dataset.lineupGroup]=ids;save();renderLineupGuideEnhanced();toast(`${box.dataset.lineupGroup}조 출전 학생을 변경했어요`)})}
function renderScoreboardEnhanced(){const c=current(),fallback=(c.matches.find(m=>!m.done)||c.matches[0]).id,sel=+($('#matchSelect').value||fallback),m=c.matches[sel-1]||c.matches[0],next=c.matches[m.id]||null;$('#progressBadge').textContent=`${m.cycle}사이클 ${m.round}경기 ${m.done?'완료':m.startedAt?'진행 중':'예정'}`;$('#nextMatchGuide').innerHTML=next?`다음: <b>${next.cycle}사이클 ${next.round}경기</b> · 출전 ${next.teams.join('·')}조 · 심판 ${refereeFor(next)}조`:'마지막 경기입니다.';$('#matchSelect').innerHTML=c.matches.map(x=>`<option value="${x.id}" ${x.id===m.id?'selected':''}>${x.cycle}사이클 ${x.round}경기 · ${x.teams.join(' / ')}</option>`).join('');$('#matchLabel').textContent=`${m.cycle}사이클 ${m.round}경기 · ${m.teams.join(' · ')} · 심판 ${refereeFor(m)}조`;$('#scoreGrid').innerHTML=m.teams.map((t,i)=>`<article class="team-score ${COLORS[i]}"><small>${COLORS[i].toUpperCase()} TEAM</small><h2>${t}조</h2><div class="big-score">${m.scores[i]}</div><div class="score-buttons"><button class="point" data-point="${i}">+ 1 득점</button><button data-foul="${i}">파울</button></div></article>`).join('');$$('[data-point]').forEach(b=>b.onclick=()=>{const before=[...m.scores];m.scores[+b.dataset.point]++;scoreLog(m,'point',`${m.teams[+b.dataset.point]}조 +1`,before,m.scores);beep(640,.08);save();render()});$$('[data-foul]').forEach(b=>b.onclick=()=>confirmFoul(m,+b.dataset.foul));$('#scoreboard').classList.toggle('scoreboard-running',Boolean(m.startedAt&&!m.done));$('.score-controls').classList.toggle('finished',Boolean(m.done));$('#startMatch').disabled=Boolean(m.startedAt&&!m.done);$('#endMatch').disabled=!m.startedAt||m.done;renderScoreHistory()}
function persistTimer(m){m.remainingSeconds=seconds;m.timerUpdatedAt=new Date().toISOString();localStorage.setItem('kinball-class-v1',JSON.stringify(state))}
function runMatchTimer(m){clearInterval(timerId);timerId=setInterval(()=>{if(seconds<=0){clearInterval(timerId);timerId=null;m.remainingSeconds=0;m.timerRunning=false;persistTimer(m);beep(880,1);$('#timerToggle').textContent='시작';toast('경기 시간이 종료됐어요')}else{seconds--;m.remainingSeconds=seconds;m.timerUpdatedAt=new Date().toISOString();updateTimer();if(seconds%5===0)persistTimer(m)}},1000);$('#timerToggle').textContent='일시정지'}
function restoreMatchTimer(m){seconds=Number.isFinite(m.remainingSeconds)?m.remainingSeconds:600;if(m.timerRunning&&!m.done){const elapsed=Math.max(0,Math.floor((Date.now()-new Date(m.timerUpdatedAt||Date.now()).getTime())/1000));seconds=Math.max(0,seconds-elapsed);m.remainingSeconds=seconds;m.timerUpdatedAt=new Date().toISOString();if(seconds>0)runMatchTimer(m)}else{$('#timerToggle').textContent='시작'}updateTimer()}
function startMatchWorkflow(){const m=current().matches[+$('#matchSelect').value-1];if(m.done)return toast('이미 종료된 경기입니다');m.startedAt=m.startedAt||new Date().toISOString();m.timerRunning=true;m.remainingSeconds=Number.isFinite(m.remainingSeconds)?m.remainingSeconds:600;m.timerUpdatedAt=new Date().toISOString();seconds=m.remainingSeconds;matchRunning=true;runMatchTimer(m);save();render();toast('경기와 타이머를 시작했어요')}
function toggleMatchTimer(){const m=current().matches[+$('#matchSelect').value-1];if(!m.startedAt)return toast('경기 시작 버튼을 먼저 누르세요');if(timerId){clearInterval(timerId);timerId=null;m.timerRunning=false;persistTimer(m);$('#timerToggle').textContent='계속'}else{m.timerRunning=true;m.timerUpdatedAt=new Date().toISOString();runMatchTimer(m);persistTimer(m)}}
