function endMatchWorkflow(){const m=current().matches[+$('#matchSelect').value-1];if(!m.startedAt)return toast('경기를 먼저 시작하세요');if(!confirm(`${m.cycle}사이클 ${m.round}경기를 종료하고 ${m.scores.join(' : ')} 점수로 저장할까요?`))return;m.done=true;m.completedAt=new Date().toISOString();m.timerRunning=false;m.remainingSeconds=seconds;matchRunning=false;clearInterval(timerId);timerId=null;$('#timerToggle').textContent='시작';save();render();renderTodaySummary();toast('결과를 저장했습니다. 다음 출전 학생과 심판을 확인하세요')}
