function endLessonWorkflow(){const games=current().matches.filter(m=>m.done);if(!confirm(`오늘 완료한 ${games.length}경기를 저장하고 수업을 종료할까요?\n저장 후에도 이전 수업에서 다시 불러올 수 있습니다.`))return;archiveCurrentLesson(true);save();renderTodaySummary();const html=$('#todayGames').innerHTML;modal('오늘 수업 저장 완료',`<div class="lesson-report"><b>${state.activeLesson.date} · ${state.activeLesson.period}차시 · ${state.settings.grade}학년 ${state.selectedClass}반</b>${html}<span>온라인 상태: ${sessionStorage.getItem('kinball-cloud-pin')?'동기화 요청 완료':'기기 저장 완료'}</span></div>`,()=>{});$('#modalSave').textContent='확인'}
function toggleLargeMode(){document.body.classList.toggle('large-score-mode');$('#largeMode').textContent=document.body.classList.contains('large-score-mode')?'보통 글씨':'큰 글씨'}
async function toggleFullscreen(){try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen()}catch{toast('이 환경에서는 전체화면을 사용할 수 없어요')}}
const oldSetCloudState=setCloudState;setCloudState=function(mode,text){oldSetCloudState(mode,text);const w=$('#syncWarning');if(w)w.hidden=mode!=='offline'||text==='기기 저장';dirtySinceCloud=mode==='saving'||(mode==='offline'&&text!=='기기 저장')}
window.addEventListener('beforeunload',e=>{if(dirtySinceCloud){e.preventDefault();e.returnValue=''}});
document.addEventListener('DOMContentLoaded',()=>{renderLessonSession();$('#newLesson').onclick=startNewLesson;$('#loadLesson').onclick=loadPreviousLesson;$('#semesterSummary').onclick=showSemesterSummary;$('#startMatch').onclick=startMatchWorkflow;$('#endMatch').onclick=endMatchWorkflow;$('#nextMatch').onclick=moveNextMatch;$('#endLesson').onclick=endLessonWorkflow;$('#undoFoul').onclick=undoLastFoul;$('#largeMode').onclick=toggleLargeMode;$('#fullscreenMode').onclick=toggleFullscreen;$('#matchSelect').onchange=()=>{renderScoreboard();renderLineupGuide()};render();renderScoreHistory()});

// Advanced lesson operation and student record features.
state.settings={grade:1,volume:.6,tieMode:'shared',teacherId:'',...(state.settings||{})};
Object.values(state.classes).forEach(c=>c.students.forEach(s=>{s.stats={points:0,defenses:0,referee:0,cooperation:0,fairPlay:0,...(s.stats||{})};s.participation=s.participation||{}}));
let scoreHistory=[],ruleTimerId=null,teacherUnlocked=sessionStorage.getItem('kinball-teacher-unlocked')==='yes';

async function syncCloud(){const id=state.settings.teacherId,pin=sessionStorage.getItem('kinball-cloud-pin');if(!id||!pin)return;setCloudState('saving','저장 중');try{const res=await fetch(CLOUD_API,{method:'PUT',headers:{'content-type':'application/json','x-teacher-id':id,'x-teacher-pin':pin},body:JSON.stringify(state)});const data=await res.json();if(!res.ok)throw new Error(data.error);state.lastCloudSave=data.updatedAt||new Date().toISOString();localStorage.setItem('kinball-class-v1',JSON.stringify(state));setCloudState('online',`온라인 저장 · ${new Date(state.lastCloudSave).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})}`)}catch(e){setCloudState('offline','동기화 실패');console.warn(e)}}
function setCloudState(mode,text){const el=$('#cloudStatus');if(!el)return;el.className=`cloud-status ${mode}`;el.textContent=text;const detail=$('#cloudDetail');if(detail)detail.textContent=mode==='online'?`${state.settings.teacherId} · 모든 변경 자동 저장`:text}
function applyCloudData(remote,id){state=remote;state.settings={grade:1,volume:.6,tieMode:'shared',teacherId:id,...(state.settings||{})};state.lessons=state.lessons||[];state.activeLesson=state.activeLesson||{date:new Date().toISOString().slice(0,10),period:1,title:'1차시'};localStorage.setItem('kinball-class-v1',JSON.stringify(state))}
function chooseCloudVersion(remote,updatedAt,id){if(!remote)return 'local';const localTime=state.lastLocalSave?new Date(state.lastLocalSave).getTime():0,remoteTime=remote.lastLocalSave?new Date(remote.lastLocalSave).getTime():new Date(updatedAt||0).getTime();if(!localTime)return 'cloud';if(Math.abs(remoteTime-localTime)<2000)return 'cloud';const useCloud=confirm(`기기와 온라인에 서로 다른 데이터가 있습니다.\n\n기기 저장: ${new Date(localTime).toLocaleString('ko-KR')}\n온라인 저장: ${new Date(remoteTime).toLocaleString('ko-KR')}\n\n[확인] 온라인 데이터 사용\n[취소] 이 기기 데이터 사용`);return useCloud?'cloud':'local'}
async function connectCloud(){const id=prompt('온라인 저장에 사용할 교사 ID를 입력하세요.','teacher01')?.trim().toLowerCase(),pin=prompt('교사 PIN을 입력하세요. (4자리 이상)')||'';if(!id||pin.length<4)return toast('교사 ID와 4자리 이상의 PIN이 필요해요');try{setCloudState('saving','연결 중');const res=await fetch(CLOUD_API,{headers:{'x-teacher-id':id,'x-teacher-pin':pin}}),data=await res.json();if(!res.ok)throw new Error(data.error);state.settings.teacherId=id;sessionStorage.setItem('kinball-cloud-pin',pin);if(data.data&&chooseCloudVersion(data.data,data.updatedAt,id)==='cloud'){applyCloudData(data.data,id);location.reload()}else{save();await syncCloud();render();toast('이 기기 데이터를 온라인에 저장했어요')}}catch(e){setCloudState('offline','연결 실패');toast(e.message||'온라인 연결에 실패했어요')}}
function updateLockUI(){const b=$('#teacherLock');if(!b)return;b.textContent=teacherUnlocked?'🔓 교사 모드':'🔒 교사 잠금';b.classList.toggle('unlocked',teacherUnlocked);document.body.classList.toggle('teacher-locked',!teacherUnlocked);const hint=$('#teacherLockHint');if(hint)hint.hidden=teacherUnlocked;$$('.teacher-only').forEach(x=>{if('disabled'in x)x.disabled=!teacherUnlocked;x.classList.toggle('locked-control',!teacherUnlocked)});['startMatch','endMatch','nextMatch','undoFoul'].forEach(id=>{const x=$('#'+id);if(x)x.title=teacherUnlocked?'':`교사 잠금을 해제해야 사용할 수 있습니다`})}
function toggleTeacherLock(){if(teacherUnlocked){teacherUnlocked=false;sessionStorage.removeItem('kinball-teacher-unlocked');updateLockUI();return toast('교사 기능을 잠갔어요')}const saved=localStorage.getItem('kinball-teacher-pin');if(!saved){const pin=prompt('새 교사 잠금 PIN을 설정하세요. (4자리 이상)')||'';if(pin.length<4)return toast('4자리 이상의 PIN이 필요해요');localStorage.setItem('kinball-teacher-pin',pin)}else if((prompt('교사 PIN을 입력하세요.')||'')!==saved)return toast('PIN이 올바르지 않아요');teacherUnlocked=true;sessionStorage.setItem('kinball-teacher-unlocked','yes');updateLockUI();toast('교사 기능을 열었어요')}

function rankFor(c){const rows=Object.fromEntries(GROUPS.map(g=>[g,{g,p:0,w:0,d:0,l:0,gf:0,ga:0,pts:0,replay:0}]));c.matches.filter(m=>m.done).forEach(m=>{const max=Math.max(...m.scores),wins=m.scores.filter(x=>x===max).length,tied=wins>1;m.teams.forEach((g,i)=>{const r=rows[g];r.p++;r.gf+=m.scores[i];r.ga+=m.scores.reduce((a,x,j)=>a+(j===i?0:x),0);if(m.scores[i]===max&&!tied){r.w++;r.pts+=3}else if(m.scores[i]===max){r.d++;if(state.settings.tieMode!=='replay')r.pts++;else r.replay++}else r.l++})});return Object.values(rows).sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf)}
function refereeFor(m){return GROUPS.find(g=>!m.teams.includes(g))||'-'}
function renderSchedule(){const c=current(),active=Math.max(0,c.matches.findIndex(m=>!m.done)),start=Math.max(0,active);$('#miniSchedule').innerHTML=c.matches.slice(start,start+3).map((m,i)=>`<div class="mini-game ${i===0&&!m.done?'current':''}"><span class="round">${m.cycle}C-${m.round}</span><div class="teams">${m.teams.map(t=>`<span>${t}</span>`).join('')} <small>심판 ${refereeFor(m)}조</small></div><span class="game-state">${m.done?'완료':i===0?'진행 중':'예정'}</span></div>`).join('');$('#scheduleGrid').innerHTML=Array.from({length:4},(_,i)=>{const cycle=i+1;return `<div class="cycle-divider"><span>${cycle}사이클</span><small>${cycle*4-3}~${cycle*4}경기</small></div>`+c.matches.filter(m=>m.cycle===cycle).map(m=>{const status=m.done?'completed':m.id===active+1?'active':'scheduled';return `<article class="game-card card ${status}"><div class="game-card-head"><b>${m.id}경기 <em>${m.cycle}사이클 ${m.round}경기</em></b><span>${m.done?'완료':status==='active'?'진행 중':'예정'}</span></div><div class="match-duty">출전 ${m.teams.join(' · ')}조 <b>심판 ${refereeFor(m)}조</b></div><div class="game-teams">${m.teams.map((t,j)=>`<div><b>${t}조</b><input type="number" min="0" value="${m.scores[j]}" data-match="${m.id}" data-score="${j}"></div>`).join('<i>:</i>')}</div><button class="btn ${m.done?'secondary':'primary'} save-result" data-match="${m.id}">${m.done?'결과 수정':'결과 저장'}</button></article>`}).join('')}).join('');$$('[data-score]').forEach(x=>x.oninput=e=>{const m=c.matches[e.target.dataset.match-1];m.scores[+e.target.dataset.score]=Math.max(0,+e.target.value||0)});$$('.save-result').forEach(b=>b.onclick=()=>{const m=c.matches[b.dataset.match-1];m.done=true;m.completedAt=new Date().toISOString();save();render();toast(`${m.cycle}사이클 경기 결과가 반영됐어요`)})}
function rememberScore(m){scoreHistory.push({classId:state.selectedClass,matchId:m.id,scores:[...m.scores]});if(scoreHistory.length>30)scoreHistory.shift();$('#undoScore').disabled=false}
function renderScoreboard(){return renderScoreboardEnhanced()}
function adjust(m,i,n){rememberScore(m);m.scores[i]=Math.max(0,m.scores[i]+n);beep(n>0?640:300,.08);save();render()}
function undoScore(){const history=persistedScoreHistory(),last=[...history].reverse().find(x=>x.type!=='undo'&&!history.some(y=>y.undoId===x.id));if(!last)return toast('되돌릴 점수가 없어요');const m=current().matches[last.matchId-1],restore=last.before;if(!m||!restore)return toast('되돌릴 수 없는 기록이에요');const before=[...m.scores];m.scores=[...restore];scoreLog(m,'undo',`${last.text} 되돌림`,before,m.scores);m.scoreHistory[m.scoreHistory.length-1].undoId=last.id;if(last.id===lastFoulEntry?.id)lastFoulEntry=null;save();render();toast(`되돌림: ${last.text} · ${before.join(':')} → ${restore.join(':')}`)}
function beep(freq=600,dur=.12){try{const a=new AudioContext(),o=a.createOscillator(),g=a.createGain();o.frequency.value=freq;o.connect(g);g.connect(a.destination);g.gain.setValueAtTime(Math.max(.001,state.settings.volume*.2),a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+dur);o.start();o.stop(a.currentTime+dur)}catch{}}

function studentLabel(s){return `${s.grade||state.settings.grade}학년 ${state.selectedClass}반 ${s.no}번`}
function renderTeamBalance(){const el=$('#teamBalance');if(!el)return;const c=current(),counts=GROUPS.map(g=>({g,total:c.students.filter(s=>s.group===g).length,present:c.students.filter(s=>s.group===g&&s.present).length})),present=counts.map(x=>x.present),gap=Math.max(0,...present)-Math.min(...present);el.innerHTML=`<strong>결석 반영 조 균형</strong>${counts.map(x=>`<div class="balance-team"><b>${x.g}조 · ${x.present}명</b><small>등록 ${x.total}명</small></div>`).join('')}<div class="${gap<=1?'balance-ok':'balance-warning'}">${c.students.length?(gap<=1?'현재 출석 인원이 고르게 편성되어 있습니다.':`조별 출석 인원이 최대 ${gap}명 차이 납니다. 조 편성을 확인하세요.`):'학생 명단을 등록하면 조별 균형을 확인합니다.'}</div>`}
function rotatingPlayers(group,matchId){const list=current().students.filter(s=>s.group===group&&s.present).sort((a,b)=>a.no-b.no);if(!list.length)return [];const count=Math.min(4,list.length),offset=((matchId-1)*count)%list.length;return Array.from({length:count},(_,i)=>list[(offset+i)%list.length])}
function lineupCard(m,label){if(!m)return `<div class="lineup-game"><span>${label}</span><em>마지막 경기입니다.</em></div>`;return `<div class="lineup-game"><span>${label} · ${m.cycle}C-${m.round}</span>${m.teams.map(g=>{const players=rotatingPlayers(g,m.id);return `<div class="lineup-team"><b>${g}조</b><em>${players.length?players.map(s=>`${s.no}번`).join(' · '):'출석 학생 없음'}</em></div>`}).join('')}<div class="lineup-team"><b>심판</b><em>${refereeFor(m)}조</em></div></div>`}
function renderLineupGuide(){return renderLineupGuideEnhanced()}
function csvCell(value){return `"${String(value??'').replaceAll('"','""')}"`}
function exportLessonCsv(){const today=new Date().toDateString(),games=current().matches.filter(m=>m.completedAt&&new Date(m.completedAt).toDateString()===today);if(!games.length)return toast('오늘 완료한 경기가 아직 없어요');const rows=[['학년','반','사이클','경기','출전 조','심판 조','점수','완료 시각'],...games.map(m=>[state.settings.grade,state.selectedClass,m.cycle,m.round,m.teams.join('·'),refereeFor(m),m.scores.join(':'),new Date(m.completedAt).toLocaleTimeString('ko-KR')]),[],['학생','조','득점 기여','수비 성공','심판 참여','협동','페어플레이'],...current().students.map(s=>[studentLabel(s),s.group,s.stats.points,s.stats.defenses,s.stats.referee,s.stats.cooperation,s.stats.fairPlay])],text='\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),blob=new Blob([text],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`킨볼-수업요약-${state.settings.grade}학년-${state.selectedClass}반-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);toast('오늘 수업 요약을 엑셀용 파일로 저장했어요')}
function renderStudents(){const c=current();$('#groupTabs').innerHTML=['전체',...GROUPS].map(g=>`<button class="${g===activeGroup?'active':''}" data-group="${g}">${g}${g==='전체'?'':'조'}</button>`).join('');$$('[data-group]').forEach(b=>b.onclick=()=>{activeGroup=b.dataset.group;renderStudents()});const list=c.students.filter(s=>activeGroup==='전체'||s.group===activeGroup).sort((a,b)=>a.no-b.no);$('#emptyStudents').style.display=list.length?'none':'block';$('#studentBody').innerHTML=list.map(s=>`<tr><td><input type="checkbox" data-present="${s.id}" ${s.present?'checked':''}></td><td><b>${studentLabel(s)}</b></td><td><span class="team-chip">${s.group}</span></td><td>${s.stats.points}</td><td>${s.stats.defenses}</td><td>${s.stats.referee}</td><td><button class="text-btn teacher-only" data-record-student="${s.id}">기록</button></td><td><button class="text-btn teacher-only" data-delete-student="${s.id}">삭제</button></td></tr>`).join('');$$('[data-present]').forEach(x=>x.onchange=()=>{c.students.find(s=>s.id==x.dataset.present).present=x.checked;save();render()});$$('[data-delete-student]').forEach(b=>b.onclick=()=>{c.students=c.students.filter(s=>s.id!=b.dataset.deleteStudent);save();render()});$$('[data-record-student]').forEach(b=>b.onclick=()=>recordStudent(+b.dataset.recordStudent));updateLockUI()}
function recordStudent(id){const s=current().students.find(x=>x.id===id),st=s.stats;modal(`${studentLabel(s)} 개인 기록`, `<div class="record-grid"><label class="field">득점 기여<input name="points" type="number" min="0" value="${st.points}"></label><label class="field">수비 성공<input name="defenses" type="number" min="0" value="${st.defenses}"></label><label class="field">심판 참여<input name="referee" type="number" min="0" value="${st.referee}"></label><label class="field">협동 점수<input name="cooperation" type="number" min="0" value="${st.cooperation}"></label><label class="field">페어플레이 점수<input name="fairPlay" type="number" min="0" value="${st.fairPlay}"></label></div><h4>경기별 출전 체크</h4><div class="participation-grid">${current().matches.map(m=>`<label><input type="checkbox" name="match${m.id}" ${s.participation[m.id]?'checked':''}> ${m.cycle}C-${m.round}</label>`).join('')}</div>`,f=>{['points','defenses','referee','cooperation','fairPlay'].forEach(k=>st[k]=Math.max(0,+f.get(k)||0));current().matches.forEach(m=>s.participation[m.id]=f.has('match'+m.id));save();render();toast('개인 기록을 저장했어요')})}
function awardCandidates(){const all=Object.entries(state.classes).flatMap(([classId,c])=>c.students.map(s=>({label:`${state.settings.grade}학년 ${classId}반 ${s.no}번`,classId:+classId,s}))),top=(key,n=8)=>all.sort((a,b)=>(b.s.stats[key]||0)-(a.s.stats[key]||0)).filter(x=>x.s.stats[key]>0).slice(0,n);return {referee:top('referee'),mvp:all.sort((a,b)=>(b.s.stats.points+b.s.stats.defenses)-(a.s.stats.points+a.s.stats.defenses)).filter(x=>x.s.stats.points+x.s.stats.defenses>0).slice(0,8),cooperation:top('cooperation'),fairPlay:top('fairPlay')}}
function renderTodaySummary(){const today=new Date().toDateString(),games=current().matches.filter(m=>m.completedAt&&new Date(m.completedAt).toDateString()===today);$('#todayGames').innerHTML=games.length?games.map(m=>`<span>${m.cycle}C-${m.round} · ${m.teams.join('·')}조 · ${m.scores.join(':')}</span>`).join(''):'<p>오늘 완료한 경기가 아직 없습니다.</p>'}

function speakRuleNumber(number){if(!('speechSynthesis'in window)||state.settings.volume<=0)return;const words=['zero','one','two','three','four','five','six','seven','eight','nine','ten'],utterance=new SpeechSynthesisUtterance(words[number]);utterance.lang='en-US';utterance.rate=1.35;utterance.pitch=1;utterance.volume=Math.min(1,state.settings.volume);window.speechSynthesis.cancel();window.speechSynthesis.speak(utterance)}
function showRuleCountdown(left,total){$('#ruleCountdownLabel').textContent=total===5?'5초 히팅':'10초 세팅';$('#ruleCountdownNumber').textContent=left;$('#ruleCountdownDisplay').hidden=false}
function finishRuleCountdown(el){clearInterval(ruleTimerId);ruleTimerId=null;$('#ruleCountdownNumber').textContent='GO!';beep(900,.5);el.classList.add('expired');setTimeout(()=>{el.classList.remove('expired');$('#ruleCountdownDisplay').hidden=true},750)}
function startRuleTimer(total){clearInterval(ruleTimerId);if('speechSynthesis'in window)window.speechSynthesis.cancel();let left=total,el=$(total===5?'#fiveTimer':'#tenTimer');el.textContent=String(left).padStart(2,'0');showRuleCountdown(left,total);speakRuleNumber(left);ruleTimerId=setInterval(()=>{left--;el.textContent=String(Math.max(0,left)).padStart(2,'0');if(left<=0)return finishRuleCountdown(el);showRuleCountdown(left,total);speakRuleNumber(left)},1000)}

const ADMIN_SELECTOR='.teacher-only,#resetLeague,#resetTrialScores,#addStudent,#bulkStudents,#resetAttendance,#exportLesson,#newLesson,#startMatch,#endMatch,#nextMatch,#undoFoul,[data-record-student],[data-delete-student],.save-result,[data-score],#resetClassMeet,#addTournament,.save-meet,[data-meet-score],#cloudConnect,#importData';
document.addEventListener('click',e=>{if(!teacherUnlocked&&e.target.closest(ADMIN_SELECTOR)){e.preventDefault();e.stopImmediatePropagation();toast('교사 PIN으로 잠금을 먼저 해제하세요')}},true);
document.addEventListener('focusin',e=>{if(!teacherUnlocked&&e.target.matches('[data-score],[data-meet-score],#importData')){e.target.blur();toast('교사 PIN으로 잠금을 먼저 해제하세요')}});
document.addEventListener('DOMContentLoaded',()=>{
  $('#teacherLock').onclick=toggleTeacherLock;$('#cloudConnect').onclick=connectCloud;$('#undoScore').onclick=undoScore;$('#undoScore').disabled=true;
  $('#matchSelect').onchange=()=>{renderScoreboard();renderLineupGuide()};
  $('#resetAttendance').onclick=()=>{if(!current().students.length)return toast('등록된 학생이 없어요');if(confirm('현재 반의 출석을 모두 출석 상태로 초기화할까요?')){current().students.forEach(s=>s.present=true);save();render();toast('출석을 초기화했어요')}};$('#exportLesson').onclick=exportLessonCsv;
  $$('[data-rule-timer]').forEach(b=>b.onclick=()=>startRuleTimer(+b.dataset.ruleTimer));
  $('#volumeControl').value=Math.round(state.settings.volume*100);$('#volumeLabel').textContent=Math.round(state.settings.volume*100)+'%';$('#volumeControl').oninput=e=>{state.settings.volume=+e.target.value/100;$('#volumeLabel').textContent=e.target.value+'%';save()};
  $('#tieSetting').value=state.settings.tieMode;$('#tieSetting').onchange=e=>{state.settings.tieMode=e.target.value;save();render()};
  $('#endMatch').onclick=()=>{const m=current().matches[+$('#matchSelect').value-1];m.done=true;m.completedAt=new Date().toISOString();save();beep(820,.7);render();renderTodaySummary();toast('경기를 종료하고 순위를 계산했어요')};
  $('#endLesson').onclick=()=>{renderTodaySummary();const html=$('#todayGames').innerHTML;modal('오늘 수업 요약',`<div class="lesson-report"><b>${state.settings.grade}학년 ${state.selectedClass}반</b>${html}</div>`,()=>{});$('#modalSave').textContent='확인'};
  $('#addStudent').onclick=()=>modal('학생 추가',`<div class="triple"><label class="field">학년<input value="${state.settings.grade}" disabled></label><label class="field">번호<input name="no" type="number" min="1" required></label><label class="field">소속 조<select name="group">${GROUPS.map(g=>`<option>${g}</option>`).join('')}</select></label></div>`,f=>{current().students.push({id:Date.now(),no:+f.get('no'),group:f.get('group'),present:true,stats:{points:0,defenses:0,referee:0,cooperation:0,fairPlay:0},participation:{}});save();render();toast('학생을 추가했어요')});
  $('#bulkStudents').onclick=()=>modal('전체 학생 명단 엑셀 일괄 등록',`<div class="bulk-help"><b>엑셀의 ‘학년·반·번호·조’ 열을 그대로 붙여넣으세요.</b><p>첫 행 제목과 조는 생략할 수 있습니다. 조가 없으면 반별 A·B·C·D조로 자동 배정됩니다.</p><code>학년　반　번호　조<br>${state.settings.grade}　1　1　A<br>${state.settings.grade}　1　2　B<br>${state.settings.grade}　2　1　A</code></div><label class="field">CSV 파일 선택(선택)<input name="rosterFile" type="file" accept=".csv,.tsv,text/csv,text/tab-separated-values"></label><label class="field">엑셀에서 복사해 붙여넣기<textarea name="roster" rows="12" placeholder="학년&#9;반&#9;번호&#9;조&#10;${state.settings.grade}&#9;1&#9;1&#9;A&#10;${state.settings.grade}&#9;1&#9;2&#9;B&#10;${state.settings.grade}&#9;2&#9;1&#9;A"></textarea></label>`,async f=>{const file=f.get('rosterFile'),raw=[String(f.get('roster')||''),file?.size?await file.text():''].filter(Boolean).join('\n'),lines=raw.split(/\r?\n/).map(x=>x.trim()).filter(x=>x&&!/^(학년|grade)[\s,\t]/i.test(x));let added=0,updated=0,skipped=0;const perClass={};lines.forEach((line,i)=>{const p=line.split(/[\t,;]+|\s+/).map(x=>x.trim()).filter(Boolean),grade=+p[0],classNo=+p[1],no=+p[2];if(!grade||!state.classes[classNo]||!no){skipped++;return}const parsed=String(p[3]||'').toUpperCase().replace('조',''),index=perClass[classNo]=(perClass[classNo]||0)+1,group=GROUPS.includes(parsed)?parsed:GROUPS[(index-1)%4],c=state.classes[classNo],old=c.students.find(s=>+s.no===no);if(old){old.group=group;old.grade=grade;old.stats=old.stats||{points:0,defenses:0,referee:0,cooperation:0,fairPlay:0};old.participation=old.participation||{};updated++}else{c.students.push({id:Date.now()+i,grade,no,group,present:true,stats:{points:0,defenses:0,referee:0,cooperation:0,fairPlay:0},participation:{}});added++}});save();render();toast(`${added}명 추가${updated?` · ${updated}명 수정`:''}${skipped?` · ${skipped}행 제외`:''}`)})
  const savedPin=sessionStorage.getItem('kinball-cloud-pin');if(savedPin&&state.settings.teacherId){const connectedId=state.settings.teacherId;setCloudState('saving','온라인 확인 중');fetch(CLOUD_API,{headers:{'x-teacher-id':connectedId,'x-teacher-pin':savedPin}}).then(r=>r.json()).then(async d=>{if(d.data&&chooseCloudVersion(d.data,d.updatedAt,connectedId)==='cloud'){applyCloudData(d.data,connectedId);restoreScoreAudit();render();renderLessonSession();setCloudState('online','온라인 데이터 사용')}else if(d.data){await syncCloud()}else{await syncCloud()}}).catch(()=>setCloudState('offline','동기화 실패'))}
  updateLockUI();renderTodaySummary();render();
});

// Keep the integrated lesson workflow as the final event binding.
document.addEventListener('DOMContentLoaded',()=>{
  $('#newLesson').onclick=startNewLesson;$('#loadLesson').onclick=loadPreviousLesson;$('#semesterSummary').onclick=showSemesterSummary;
  $('#resetTrialScores').onclick=resetTrialScores;
  $('#startMatch').onclick=startMatchWorkflow;$('#endMatch').onclick=endMatchWorkflow;$('#nextMatch').onclick=moveNextMatch;$('#endLesson').onclick=endLessonWorkflow;
  $('#undoFoul').onclick=undoLastFoul;$('#largeMode').onclick=toggleLargeMode;$('#fullscreenMode').onclick=toggleFullscreen;
  $('#matchSelect').onchange=e=>changeSelectedMatch(+e.target.value);$('#timerToggle').onclick=toggleMatchTimer;$('#timerReset').onclick=resetMatchTimer;
  renderLessonSession();restoreScoreAudit();render();displayedMatchId=+$('#matchSelect').value;restoreMatchTimer(current().matches[displayedMatchId-1]);renderScoreHistory();updateLockUI();
});

document.addEventListener('DOMContentLoaded',()=>{
  const quiz=$('#lessonQuiz');
  if(!quiz)return;
  const updateQuiz=()=>{const fields=[...quiz.querySelectorAll('fieldset')],answered=fields.filter(f=>f.dataset.choice),total=fields.length;if(answered.length<total){$('#quizResult').textContent=`${answered.length}/${total} 답변 완료 · 모든 문제에 답해 보세요.`;return}const score=fields.filter(f=>f.dataset.choice===f.dataset.answer).length;$('#quizResult').textContent=score===total?`${score}/${total} 정답! 이제 체육관에서 함께 움직여 봅시다.`:`${score}/${total} 정답 · 틀린 문제의 핵심 규칙을 다시 살펴보세요.`;$('#quizResult').classList.toggle('perfect',score===total)};
  quiz.querySelectorAll('[data-choice]').forEach(button=>button.onclick=()=>{const field=button.closest('fieldset');field.dataset.choice=button.dataset.choice;field.querySelectorAll('button').forEach(b=>b.classList.remove('selected','correct','wrong'));button.classList.add(button.dataset.choice===field.dataset.answer?'correct':'wrong');updateQuiz()});
});
